# 9. Importancias de variables (RF) y extracción de nombres resultantes
import numpy as np
import pandas as pd
import sklearn
from pprint import pprint

print("scikit-learn version:", sklearn.__version__)

# 0) Comprobaciones iniciales
if 'pipe_rf' not in globals():
    raise RuntimeError("No se encontró 'pipe_rf' en el espacio global. Ejecuta la Celda 5 para definir el pipeline.")

# localizar el preprocessor dentro del pipeline (puede llamarse 'preprocessor' o 'pre')
pre = None
if 'preprocessor' in pipe_rf.named_steps:
    pre = pipe_rf.named_steps['preprocessor']
elif 'pre' in pipe_rf.named_steps:
    pre = pipe_rf.named_steps['pre']
else:
    # intentar detectar ColumnTransformer entre pasos
    for name, step in pipe_rf.named_steps.items():
        from sklearn.compose import ColumnTransformer
        if isinstance(step, ColumnTransformer):
            pre = step
            break

if pre is None:
    raise RuntimeError("No se pudo localizar el ColumnTransformer preprocessor dentro de pipe_rf.named_steps.")

print("Found preprocessor object:", type(pre), getattr(pre, "uid", ""))

# 1) Asegurar que el preprocessor está 'fitted' para poder extraer nombres
fitted = False
try:
    # ColumnTransformer fitted if has attribute named_transformers_
    fitted = hasattr(pre, "named_transformers_") and len(pre.named_transformers_) > 0
except Exception:
    fitted = False

if not fitted:
    # Necesitamos tener X_train definido para ajustar el preprocessor temporalmente
    if 'X_train' not in globals():
        raise RuntimeError("El preprocessor no está fit y no existe X_train para ajustarlo. Ejecuta la Celda 6 (split) primero.")
    # Ajustar solo el preprocessor con X_train (no cambia pipe_rf)
    print("Ajustando temporalmente el preprocessor con X_train para poder extraer nombres de features...")
    pre.fit(X_train)
    print("Preprocessor ajustado temporalmente.")

# 2) Extraer nombres numéricos y nombres resultantes del OneHotEncoder
# Obtener num_cols y cat_cols si existen
num_cols_local = None
cat_cols_local = None
if 'num_cols' in globals():
    num_cols_local = list(num_cols)
if 'cat_cols' in globals():
    cat_cols_local = list(cat_cols)

# Si no están definidas, inferir de X_train
if num_cols_local is None or cat_cols_local is None:
    if 'X_train' in globals():
        num_cols_local = X_train.select_dtypes(include=['int64','float64']).columns.tolist()
        cat_cols_local = X_train.select_dtypes(include=['object','category','bool']).columns.tolist()
    else:
        raise RuntimeError("No se encontraron num_cols/cat_cols ni X_train para inferirlas.")

print("num_cols used:", num_cols_local)
print("cat_cols used:", cat_cols_local)

# Extraer nombres OHE de forma robusta
ohe_names = []
try:
    # acceder al transformador 'cat' dentro del ColumnTransformer
    # la key puede ser 'cat' en la definición original, pero aquí buscamos cualquier transformer que tenga 'onehot' dentro
    ct = pre  # ColumnTransformer
    # identificar el transformer que contiene OneHotEncoder
    for name, transformer in ct.named_transformers_.items():
        # transformer puede ser Pipeline -> buscar onehot dentro
        try:
            # Si es pipeline
            if hasattr(transformer, "named_steps"):
                if 'onehot' in transformer.named_steps:
                    ohe = transformer.named_steps['onehot']
                else:
                    # buscar primer OneHotEncoder en named_steps
                    ohe = None
                    for sub in transformer.named_steps.values():
                        from sklearn.preprocessing import OneHotEncoder
                        if isinstance(sub, OneHotEncoder):
                            ohe = sub
                            break
            else:
                # transformer directo, puede ser OneHotEncoder
                ohe = transformer if transformer.__class__.__name__ == 'OneHotEncoder' else None
        except Exception:
            ohe = None

        if ohe is None:
            continue

        # intentar get_feature_names_out (nueva API) con las columnas categóricas asociadas
        try:
            # obtener las columnas que alimentaron este transformer desde ct
            cols_for_transformer = []
            for name_i, cols in ct.transformers:
                if name_i == name:
                    cols_for_transformer = cols if isinstance(cols, (list, tuple)) else [cols]
                    break
            if hasattr(ohe, "get_feature_names_out"):
                out_names = list(ohe.get_feature_names_out(cols_for_transformer))
            elif hasattr(ohe, "get_feature_names"):
                out_names = list(ohe.get_feature_names(cols_for_transformer))
            else:
                out_names = []
            ohe_names.extend(out_names)
        except Exception as e:
            # fallback: crear nombres genéricos por columna categórica
            try:
                cols_for_transformer = []
                for name_i, cols in ct.transformers:
                    if name_i == name:
                        cols_for_transformer = cols if isinstance(cols, (list, tuple)) else [cols]
                        break
                for c in cols_for_transformer:
                    ohe_names.append(f"{c}_ohe_component")
            except Exception:
                pass

except Exception as e:
    print("Aviso: no se pudieron extraer nombres OHE de forma automática:", e)

# Combinar nombres numéricos + ohe_names
feature_names = list(num_cols_local) + ohe_names
print(f"Total features (estimado): {len(feature_names)}")
if len(feature_names) > 0:
    print("Primeros 20 nombres de features:", feature_names[:20])
else:
    print("No se extrajeron nombres de features; continuaremos con índice genérico.")

# 3) Extraer importancias del RF de forma segura
if 'pipe_rf' in globals() and 'rf' in pipe_rf.named_steps:
    rf_model = pipe_rf.named_steps['rf']
else:
    # tratar de localizar RandomForestRegressor en el pipeline final
    rf_model = None
    for step_name, step in pipe_rf.named_steps.items():
        from sklearn.ensemble import RandomForestRegressor
        if isinstance(step, RandomForestRegressor):
            rf_model = step
            break

if rf_model is None:
    raise RuntimeError("No se pudo localizar el RandomForestRegressor entrenado en pipe_rf.named_steps. Asegúrate de haber ejecutado pipe_rf.fit(X_train, y_train).")

importances = rf_model.feature_importances_
print("Longitud de importances del RF:", len(importances))

# 4) Emparejar importancias con nombres (si longitudes diferentes, manejar con índice)
if len(feature_names) == len(importances):
    feat_imp = pd.Series(importances, index=feature_names).sort_values(ascending=False)
else:
    # si hay desajuste, construir nombres genéricos para los índices faltantes
    if len(feature_names) < len(importances):
        # crear sufijos genéricos para cubrir la diferencia
        extra = [f"feature_{i}" for i in range(len(feature_names), len(importances))]
        feature_names_extended = feature_names + extra
    else:
        # si feature_names > importances (raro), truncar
        feature_names_extended = feature_names[:len(importances)]
    feat_imp = pd.Series(importances, index=feature_names_extended).sort_values(ascending=False)
    print("Aviso: hubo desajuste entre nombres extraídos y longitud de importancias. Se usaron nombres genéricos o truncamiento.")

# 5) Mostrar top 10 y devolver objeto para inspección
print("\nTop 10 variables importantes (Random Forest):")
display(feat_imp.head(10))

# retornar la serie para uso posterior
feat_imp_top10 = feat_imp.head(10)

