try:
    if 'y_test' in globals() and 'y_pred_lr' in globals():
        checks['MAE_LR'] = mean_absolute_error(y_test, y_pred_lr)
        checks['RMSE_LR'] = mean_squared_error(y_test, y_pred_lr, squared=False)
