    else:
        checks['MAE_LR'] = checks['RMSE_LR'] = checks['R2_LR'] = None
except Exception as e:
    checks['MAE_LR'] = checks['RMSE_LR'] = checks['R2_LR'] = f"error: {e}"

# 5) Nombres de features resultantes (si preprocessor está fitted)
try:
    feat_names = None
    if 'pipe_rf' in globals():
        pre = pipe_rf.named_steps.get('preprocessor') or pipe_rf.named_steps.get('pre')
        if pre is not None:
            # intentar extraer nombres (funciona si el preprocessor fue fit)
